//note(dgmid): populate folder menu — render as collapsible tree view

function buildFolderList( folders ) {
	
	$('#folderlist').empty()
	
	// Build a tree structure from the flat list using parent_folder
	function buildTree( flatList ) {
		
		let map = {},
		    roots = []
		
		// First pass: index by id
		for( let f of flatList ) {
			map[ f.id ] = { id: f.id, text: f.text, parent_folder: f.parent_folder, children: [] }
		}
		
		// Second pass: build parent-child relationships
		for( let f of flatList ) {
			
			if( f.parent_folder && f.parent_folder !== -1 && map[ f.parent_folder ] ) {
				
				map[ f.parent_folder ].children.push( map[ f.id ] )
				
			} else {
				
				roots.push( map[ f.id ] )
			}
		}
		
		// Sort alphabetically at each level (locale-aware: accents, Ñ, case)
		function sortTree( nodes ) {
			
			nodes.sort( _cmpNameObjects )
			
			for( let n of nodes ) {
				if( n.children.length ) sortTree( n.children )
			}
		}
		sortTree( roots )
		
		return roots
	}
	
	// Render tree recursively as nested <ul>/<li>
	function renderTree( nodes, depth ) {
		
		if( !nodes || nodes.length === 0 ) return ''
		
		let html = '<ul class="folder-tree">'
		
		for( let node of nodes ) {
			
			let hasChildren = node.children && node.children.length > 0
			
			html += `<li class="folder-tree-item${hasChildren ? ' has-children' : ''}" data-folder-id="${node.id}">`
			
			if( hasChildren ) {
				html += `<span class="folder-toggle" style="left:${6 + depth * 18}px;"></span>`
			}
			
			html += `<a href="#" class="filter folder" data-id="${node.id}" data-filter="${node.id}" data-name="${escape(node.text)}" draggable="true" style="padding-left:${30 + depth * 18}px;background-position:left ${16 + depth * 18}px top 5px;">${node.text}</a>`
			
			if( hasChildren ) {
				html += renderTree( node.children, depth + 1 )
			}
			
			html += '</li>'
		}
		
		html += '</ul>'
		return html
	}
	
	let tree = buildTree( folders )
	let html = renderTree( tree, 0 )
	$('#folderlist').html( html )
	
	//note(dgmid): re-apply the ⌘/Ctrl multi-selection highlight after every re-render
	for( let id of _multiSel ) {
		
		let a = $(`#folderlist .filter.folder[data-id="${id}"]`)
		if( a.length ) a.addClass( 'multiselected' )
	}
}


