		anchor.parents( '.folder-tree-item.collapsed' ).removeClass( 'collapsed' )
		
		//note(dgmid): scroll the sidebar so the selected folder is visible without manual scrolling
		try {
			anchor[0].scrollIntoView( { block: 'nearest' } )
		} catch( _e ) {}
		
		anchor.trigger( 'click' )
