//note(dgmid): shared drop-target helpers (strip cards + sidebar tree)

function setDragFeedback( targetEl, targetId ) {
	
	targetEl.removeClass( 'drag-over invalid' )
	
	if( _dragType === 'folder' && _dragInvalid && _dragInvalid.has( targetId ) ) {
		
		targetEl.addClass( 'invalid' )
		
	} else {
		
		targetEl.addClass( 'drag-over' )
	}
}

function handleFolderDrop( targetId ) {
	
	let type 	= _dragType,
		id 		= _dragId,
		invalid = _dragInvalid
	
	clearDragState()
	
	if( type === 'folder' ) {
		
		let ids = ( _dragIds && _dragIds.length ) ? Array.from( _dragIds ) : ( id != null ? [ id ] : [] )
		
		//note(dgmid): nothing moves when the target is one of the dragged folders
		//themselves or a folder inside their subtree (invalid set built on dragstart)
		if( !ids.length || invalid == null || invalid.has( targetId ) ) return
		
		moveFolderBulk( ids, targetId )
		
	} else if( type === 'bookmark' && id != null ) {
		
		//note(dgmid): single-row drags come through _dragIds too (see dragstart above)
		let ids = ( _dragIds && _dragIds.length ) ? Array.from( _dragIds ) : [ id ]
		
		moveBookmarksBulk( ids, targetId )
	}
}


//note(dgmid): sidebar folder tree — also a drop target for bookmarks and folders

$('.folderlist').on( 'dragover', '.filter.folder', function( e ) {
	
	if( _dragType === null ) return
	
	e.preventDefault()
	e.originalEvent.dataTransfer.dropEffect = 'move'
	
	setDragFeedback( $(this), parseInt( $(this).data( 'id' ), 10 ) )
})

$('.folderlist').on( 'dragleave', '.filter.folder', function( e ) {
	
	//note(dgmid): only clear when the pointer leaves the item itself
	if( !$(this).has( e.relatedTarget ).length && e.relatedTarget !== this ) {
		
		$(this).removeClass( 'drag-over invalid' )
	}
})

$('.folderlist').on( 'drop', '.filter.folder', function( e ) {
	
	e.preventDefault()
	e.stopPropagation()
	
	handleFolderDrop( parseInt( $(this).data( 'id' ), 10 ) )
})

function clearDragState() {
	
	_dragType 	= null
	_dragId 	= null
	_dragInvalid = null
	
	_justDragged = true
	setTimeout( () => { _justDragged = false }, 300 )
	
	$('#folder-strip .folder-card').removeClass( 'dragging drag-over invalid' )
	$('.folderlist .filter.folder').removeClass( 'drag-over invalid dragging' )
	$('#bookmarks tbody tr.dragging').removeClass( 'dragging' )
}


//note(dgmid): get list of tags with count

function buildTagList( array, noTag ) {
	
	$('.taglist').html( '' )
	
	let compressed = [],
	copy = array.slice(0)
	
	for (var i = 0; i < array.length; i++) {
	
		var myCount = 0
		
		for (var w = 0; w < copy.length; w++) {
			
			if (array[i] == copy[w]) {
				
				myCount++
				delete copy[w]
			}
		}
		
		if (myCount > 0) {
			
			var a = new Object()
			a.value = array[i]
			a.count = myCount
			compressed.push(a)
		}
	}
	
	
	let results = [],
	untagged = '',
	brokenTag = '',
	count = 1
	
	for ( let tagitem of compressed ) {
		
		if( tagitem.value === noTag ) {
			
			untagged =
			
			`<dd class="margin-top">
				<a href="#" class="filter untagged" data-filter="${escape(tagitem.value)}">
					<span class="filter-icon icon-untagged"></span>
					<span class="filter-name">${entities.encode(tagitem.value)}</span>
					<span class="filter-count">${tagitem.count}</span>
				</a>
			</dd>`
		
		} else if( tagitem.value === 'broken' ) {
			
			var color = generate(tagitem.value)
			
			brokenTag =
			
			`<dd>
				<a href="#" class="filter tagfilter" data-id="${count}" data-filter="${entities.encode(tagitem.value)}">

						<span class="tag" title="${entities.encode(tagitem.value)}" style="background-color: ${color};">${entities.encode(tagitem.value)}</span> <span class="filter-name">${entities.encode(tagitem.value)}</span>

					<span class="filter-count">${tagitem.count}</span></a>
			</dd>`
			
			results.push( { "id": count , "text": tagitem.value } )
			count++
		
		} else {
			
			var color = generate(tagitem.value)
			
			$('#taglist').append(
			
			`<dd>
				<a href="#" class="filter tagfilter" data-id="${count}" data-filter="${entities.encode(tagitem.value)}">

						<span class="tag" title="${entities.encode(tagitem.value)}" style="background-color: ${color};">${entities.encode(tagitem.value)}</span> <span class="filter-name">${entities.encode(tagitem.value)}</span>

					<span class="filter-count">${tagitem.count}</span></a>
			</dd>`
			)
			
			results.push( { "id": count , "text": tagitem.value } )
			count++
		}
	}
	
	
	store.set('tags', results )
	
	
	$('#taglist-extras').append( `${untagged}` )
	
	// Prepend 'broken' to #taglist so it sits right after 'un-tagged' (above #taglist-extras)
	// but with the same padding/styling as regular tags
	if( brokenTag ) {
		$('#taglist').prepend( brokenTag )
	}
	$('#filter-all').append(
		 `<dd>
			<a href="#" class="filter all  selected" data-filter="">
				<span class="filter-icon icon-bookmarks"></span>
				<span class="filter-name">${i18n.t('app:sidebar.filter.all','All Bookmarks')}</span>
				<span class="filter-count">${total}</span>
			</a>
		</dd>` )
	
	$('#sidebar').fadeIn( 400 )
	
	//note(dgmid): rebuilds (refresh / parse) wipe the sidebar DOM — restore the
	//multi-tag highlights and toolbar state from the persistent selection
	updateTagSelectionUI()
	updateTagToolbar()
	
	loader( 'remove' )
}



