ipcRenderer.on('delete-selected-bookmarks', (event, message) => {
	
	let selectedRows = maintable.bookmarkTable.rows({ selected: true }).data().toArray()
	
	if( selectedRows.length === 0 ) {
		
		ipcRenderer.send('show-error-box', {
			title: i18n.t('app:errorbox.title.deletebookmark', 'Delete Bookmark Error'),
			content: i18n.t('app:errorbox.content.deleteselected', 'No bookmarks are selected. Use Ctrl+Click or Shift+Click to select multiple bookmarks, then try again.')
		})
		return
	}
	
	let response = ipcRenderer.sendSync('show-message-box', {
		message: i18n.t('app:dialog.message.deleteselected', 'Are you sure you want to delete {{count}} selected bookmarks?', {count: selectedRows.length}),
		detail: i18n.t('app:dialog.detail.deleteselected', 'This operation is not reversable.'),
		buttons: [
			i18n.t('app:dialog.button.deleteselected', 'Delete {{count}} Bookmarks', {count: selectedRows.length}),
			i18n.t('app:dialog.button.cancel', 'Cancel')
		]
	})
	
	if( response === 0 ) {
		
		let ids = []
		for( let row of selectedRows ) {
			ids.push( row[0] )
		}
		
		// Delete all bookmarks sequentially
		let deleteIndex = 0
		
		function deleteNext() {
			
			if( deleteIndex >= ids.length ) {
				
				//note(dgmid): instant local update — remove the rows and update the sidebar
				let idSet = new Set( ids )
				_rawBookmarks = _rawBookmarks.filter( b => !idSet.has( b.id ) )
				
				for( let id of ids ) {
					removeBookmarkRowLocal( id, false )
				}
				refreshSidebar()
				return
			}
			
			fetch.bookmarksApi('delete', ids[deleteIndex], '', function() {
				
				deleteIndex++
				deleteNext()
			})
		}
		
		deleteNext()
	}
})


