//note(dgmid): add to and delete from folder

ipcRenderer.on('move-bookmark', (event, message) => {
	
	if( message.method === 'deletefromfolder' && message.count < 2 ) {
		
		let response = ipcRenderer.sendSync('show-message-box', {
			message: i18n.t('app:dialog.message.deletefromfolder', 'Are you sure you want to delete the current bookmark from this folder?'),
			detail: i18n.t('app:dialog.detail.deletefromfolder', 'Deleting the current bookmark from this folder will also delete the bookmark.'),
			buttons: [i18n.t('app:dialog.button.deletefromfolder', 'Delete Bookmark'), i18n.t('app:dialog.button.cancel', 'Cancel')]
		})
		
		if( response === 0 ) {
			
			moveBookmark( message.method, message.folder_id, message.bookmark_id )	
		}
	
	} else {
		
		moveBookmark( message.method, message.folder_id, message.bookmark_id )
	}
	
	function moveBookmark( method, folder_id, bookmark_id ) {
	
		fetch.bookmarksApi( message.method, message.folder_id, `/bookmarks/${message.bookmark_id}`, function() {
			
			//note(dgmid): deletefromfolder on the bookmark's last membership deletes the
			//bookmark entirely — drop its row locally.
			
			if( method === 'deletefromfolder' && message.count < 2 ) {
				
				_rawBookmarks = _rawBookmarks.filter( b => b.id !== bookmark_id )
				removeBookmarkRowLocal( bookmark_id )
				
				return
			}
			
			//note(dgmid): addtofolder / deletefromfolder adjust folder membership in a
			//way that's easiest to trust from the server — fetch just this one bookmark
			//(a single lightweight request) and update its row locally.
			
			fetch.bookmarksApi( 'single', bookmark_id, '', function( message ) {
				
				if( !message ) {
					refreshAll()
					return
				}
				
				try {
					
					let doc 		= JSON.parse( message ),
						item 	= doc['item']
					
					let bm = _rawBookmarks.find( b => b.id === bookmark_id )
					
					if( bm ) {
						
						bm.folders = item.folders
						bm.tags 	= item.tags
						
						updateBookmarkRowLocal( bm )
						
					} else {
						
						refreshAll()
					}
					
				} catch( e ) {
					
					refreshAll()
				}
			})
		})
	}
})


