//note(dgmid): auto-tag bookmarks with AI — passes selected data via store (bridge between windows).
//The modal supports TWO scopes: if bookmarks are selected it acts on exactly those
//(selection mode); otherwise it falls back to the current folder's bookmarks, with an
//optional "include subfolders" scope (folder mode), mirroring the auto-organize modal.

ipcRenderer.on('auto-tag-bookmarks', (event, message) => {
	
	// Save selected bookmarks to a temp store key for the modal to read
	// (the modal runs in a separate BrowserWindow and can't access our DataTable)
	try {
		let selectedRows = maintable.bookmarkTable.rows({ selected: true }).data().toArray()
		
		let selection = selectedRows.map( r => ({
			id: r[0],
			title: (r[2] || '').toString(),
			url: (r[4] || '').toString()
		}))
		
		store.set( '_autoTagSelection', selection )
		
	} catch( e ) {
		
		log.error( 'auto-tag: failed to read selection: ' + e.message )
		store.set( '_autoTagSelection', [] )
	}
	
	//note(dgmid): folder-mode context — the current folder + EVERY bookmark with its
	//folder assignments, so the modal can filter direct vs. recursive (include subfolders)
	//on its own, exactly like the auto-organize modal. Only built when NO bookmarks are
	//selected (selection mode doesn't need it — skips a synchronous disk write of the
	//whole catalogue).
	if( ( store.get( '_autoTagSelection' ) || [] ).length === 0 ) {
		
		let folderId 	= getCurrentFolder(),
			folderName 	= 'Home'
		
		if( folderId !== -1 ) {
			
			let folders = store.get( 'folders' ) || [],
				folder 	= folders.find( x => x.id === folderId )
			
			if( folder ) folderName = folder.text
		}
		
		try {
			
			let rows = maintable.bookmarkTable.rows().data().toArray()
			
			let allBookmarks = rows.map( r => ({
				id: r[0],
				title: (r[2] || '').toString(),
				url: (r[4] || '').toString(),
				folders: String(r[9] || '').split(',').map( x => parseInt( x, 10 ) ).filter( n => Number.isInteger( n ) )
			}))
			
			store.set( '_autoTagContext', {
				folderId: folderId,
				folderName: folderName,
				bookmarks: allBookmarks
			})
			
		} catch( e ) {
			
			log.error( 'auto-tag: failed to read folder context: ' + e.message )
			store.set( '_autoTagContext', { folderId: -1, folderName: 'Home', bookmarks: [] } )
		}
	}
	
	//note(dgmid): the user's existing tag vocabulary (with counts and example titles)
	//so the modal's "consider existing tags" option has something to feed the AI.
	//Built from the local mirror — no extra server round-trip.
	try {
		
		let tagMap = new Map()
		
		for( let bm of _rawBookmarks ) {
			
			let tags = Array.isArray( bm.tags ) ? bm.tags : []
			
			for( let t of tags ) {
				
				let tag = String( t ).trim().toLowerCase()
				if( !tag ) continue
				
				if( !tagMap.has( tag ) ) tagMap.set( tag, { tag: tag, count: 0, examples: [] } )
				
				let entry = tagMap.get( tag )
				entry.count++
				if( entry.examples.length < 3 && bm.title ) entry.examples.push( String( bm.title ).substring( 0, 80 ) )
			}
		}
		
		let vocab = [ ...tagMap.values() ].sort( (a, b) => b.count - a.count ).slice( 0, 60 )
		
		store.set( '_autoTagVocabulary', vocab )
		
	} catch( e ) {
		
		log.error( 'auto-tag: failed to collect vocabulary: ' + e.message )
		store.set( '_autoTagVocabulary', [] )
	}
	
	modalWindow.openModal( 'file://' + __dirname + '/../html/auto-tag.html', 480, 560, false )
})



